"""Near-duplicate detection over k-gram shingle sets.

Two implementations with identical semantics for the "Jaccard >= threshold"
pair set:

  * brute_force()      -- O(n^2) pairwise Jaccard over shingle sets.
  * fast_detect()      -- hashed shingles + inverted index; only pairs that
                          share at least MIN_SHARED shingles get scored.

Correctness of the candidate filter (why >= 5 shared shingles never loses a
true pair): documents here have ~197 4-gram shingles. If a pair has
Jaccard J = I / (|A| + |B| - I) >= 0.4, then
    I >= 0.4 * (|A| + |B|) / 1.4 ~ 0.286 * (197 + 197) ~= 112,
far above MIN_SHARED = 5. So every qualifying pair survives the filter, and
the scored candidates are exactly re-scored with the same set Jaccard as the
brute-force method.

Shingles are hashed to unsigned 64-bit values (blake2b). With ~118k distinct
shingles across the corpus, the expected number of 64-bit collisions is
n^2 / 2^65 < 1e-9, i.e. hashing cannot measurably change any Jaccard score,
so fast and brute force return identical results.
"""

import hashlib
from collections import defaultdict

K = 4                 # shingle width in tokens
MIN_SHARED = 5        # minimum shared shingles for a pair to be scored
THRESHOLD = 0.4       # Jaccard decision threshold


def tokenize(text):
    return text.split()


def shingle_set(tokens, k=K):
    """Set of stable 64-bit hashes of all k-grams of the token list."""
    grams = (" ".join(tokens[i:i + k]).encode() for i in range(len(tokens) - k + 1))
    return {
        int.from_bytes(hashlib.blake2b(g, digest_size=8).digest(), "big")
        for g in grams
    }


def jaccard(a, b):
    inter = len(a & b)
    union = len(a | b)
    return inter / union if union else 0.0


def brute_force(sets, threshold=THRESHOLD):
    """All pairs (i, j), i < j, with Jaccard(sets[i], sets[j]) >= threshold."""
    results = {}
    n = len(sets)
    for i in range(n):
        si = sets[i]
        for j in range(i + 1, n):
            jacc = jaccard(si, sets[j])
            if jacc >= threshold:
                results[(i, j)] = jacc
    return results


def fast_detect(sets, threshold=THRESHOLD, min_shared=MIN_SHARED):
    """Inverted-index near-duplicate detection.

    1. Index each shingle -> list of docs containing it.
    2. Count co-occurrences: pair (i, j) accumulates one hit per shared shingle.
    3. Score only pairs whose shared-shingle count >= min_shared (see module
       docstring for why this cannot drop a true positive at threshold 0.4).
    """
    index = defaultdict(list)
    for i, s in enumerate(sets):
        for h in s:
            index[h].append(i)

    shared = defaultdict(int)
    for i, s in enumerate(sets):
        for h in s:
            postings = index[h]
            if len(postings) > 1:
                for j in postings:
                    if j > i:
                        shared[(i, j)] += 1

    results = {}
    for (i, j), cnt in shared.items():
        if cnt >= min_shared:
            jacc = jaccard(sets[i], sets[j])
            if jacc >= threshold:
                results[(i, j)] = jacc
    return results


def build_sets(docs):
    """Shingle all documents once (shared preprocessing for both methods)."""
    return [shingle_set(tokenize(d)) for d in docs]

